#!/usr/bin/env bash
set -euo pipefail

# generate-bootstrap-sql.sh
# Generates a single idempotent bootstrap.sql from all ordered migrations.
# The output can cold-start a database from scratch but refuses to run
# if drizzle migrations have already been applied.

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
MIGRATE_DIR="$SCRIPT_DIR/../db/migrate"
OUTPUT="$SCRIPT_DIR/../db/bootstrap.sql"

if [ ! -d "$MIGRATE_DIR" ]; then
	echo "ERROR: Migration directory not found: $MIGRATE_DIR" >&2
	exit 1
fi

{
	cat <<'HEADER'
-- AUTO-GENERATED by generate-bootstrap-sql.sh — do not edit manually.
-- This file applies all migrations idempotently for cold-start bootstrapping.
-- It will abort if drizzle migrations have already been applied.

BEGIN;

DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		WHERE table_schema = 'drizzle' AND table_name = '__drizzle_migrations'
	) THEN
		IF EXISTS (SELECT 1 FROM drizzle.__drizzle_migrations LIMIT 1) THEN
			RAISE EXCEPTION 'drizzle.__drizzle_migrations already has rows. Use drizzle-kit migrate instead of bootstrap.sql.';
		END IF;
	END IF;
END;
$$;

HEADER

	for f in "$MIGRATE_DIR"/0*.sql; do
		echo "-- ========== $(basename "$f") =========="
		sed \
			-e 's/\bCREATE TABLE\b\( \+IF NOT EXISTS\)\{0,\}/CREATE TABLE IF NOT EXISTS/g' \
			-e 's/\bADD COLUMN\b\( \+IF NOT EXISTS\)\{0,\}/ADD COLUMN IF NOT EXISTS/g' \
			"$f"
		echo ""
	done

	echo "COMMIT;"
} > "$OUTPUT"

echo "Generated $OUTPUT ($(wc -l < "$OUTPUT" | tr -d ' ') lines)"
